#include "Singer/SingerManager.h"
namespace myvocal { void SingerManager::scan(const std::filesystem::path&root){m_singers.clear();if(!std::filesystem::exists(root))return;for(const auto&e:std::filesystem::directory_iterator(root)){if(!e.is_directory())continue;add(e.path());}} bool SingerManager::add(const std::filesystem::path&p){auto s=std::make_shared<Singer>(p);if(!s->load())return false;m_singers.push_back(std::move(s));return true;} const std::vector<std::shared_ptr<Singer>>&SingerManager::singers()const noexcept{return m_singers;} std::shared_ptr<Singer>SingerManager::findByName(const QString&n)const{for(const auto&s:m_singers)if(s->info().name.compare(n,Qt::CaseInsensitive)==0)return s;return nullptr;} }
